function hashId(value) {
  let h = 2166136261;
  value = String(value || '');
  for (let i=0;i<value.length;i++) {
    h ^= value.charCodeAt(i);
    h = Math.imul(h,16777619);
  }
  return (h>>>0).toString(16).padStart(8,'0');
}

return $input.all().map(item => {
  const j = item.json || {};
  const b = j.body || {};

  const title = String(
    b.custom_title || 'WPD EMS Radio Alert'
  ).trim();

  const message = String(
    b.transcript || b.formatted_message || b.message || ''
  ).trim();

  const location = String(
    b.location || b.address || ''
  ).trim();

  const dashboard = String(
    b.dashboard_link || ''
  ).replace('localhost','100.94.203.47');

  const now = new Date().toISOString();
  const sid = hashId(title + '|' + message + '|' + location);

  const alert = {
    schema_version: '1.0',
    alert_id: 'WPD_RADIO:' + sid,
    source: 'WPD_RADIO',
    source_event_id: sid,
    category: 'EMS',
    subtype: 'RADIO_EMS_PAGE',
    status: 'ACTIVE',
    event_action: 'NEW',
    title,
    message: message || 'EMS radio page received.',
    priority: 5,
    county: '',
    municipality: '',
    location: {
      label: location,
      address: location,
      state: '',
      zip: '',
      latitude: null,
      longitude: null,
      block: '',
      lot: '',
      qualifier: '',
      parcel_id: ''
    },
    tags: ['radio','ems','urgent','wpd'],
    click_url: dashboard,
    source_url: dashboard,
    observed_at: now,
    source_updated_at: null,
    received_at: now,
    expires_at: null,
    metadata: {
      is_ems: b.is_ems ?? true,
      dashboard_link: dashboard
    }
  };

  alert.search_text = [
    alert.source,
    alert.category,
    alert.subtype,
    location,
    title,
    message,
    ...alert.tags
  ].filter(Boolean).join(' ');

  return {json: alert};
});
